window.SHEET_DATA = {"group": {"id": "group", "title": "Skupinový náslech", "items": [{"type": "text", "text": "UPV · 2026/2027 · 2. ročník · 3. semestr (zimní)", "heading": false}, {"type": "text", "text": "Skupinový náslech", "heading": true}, {"type": "text", "text": "Záznam jedné výukové jednotky a její rozbor", "heading": false}, {"type": "text", "text": "K čemu list slouží  Zachytíte vztah mezi činností učitele a reakcí žáků v jedné navštívené hodině.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  Před hodinou doplňte údaje a zaměření. Během celé jednotky zapisujte průběh. Po ní doplňte rozbor.", "heading": false}, {"type": "text", "text": "Jak postupovat  Volby jsou pomůcka. Ke každému závěru doplňte konkrétní situaci, reakci žáků a vlastní vysvětlení.", "heading": false}, {"type": "input", "label": "Jméno studenta"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum a třída nebo skupina"}, {"type": "choice", "label": "Druh jednotky  Vyberte jednu možnost.", "multi": false, "options": ["Teoretická výuka", "Odborný výcvik nebo odborná praxe"]}, {"type": "text", "text": "Metodika 02: dva týdny ve skupině nejvýše pěti studentů, 10 teoretických a 2 praktické náslechy. Pro každou jednotku vyplňte vlastní list.", "heading": false}, {"type": "textarea", "label": "Téma a očekávaný výsledek žáka\nCo má žák vysvětlit, provést nebo posoudit? Doplňte počet přítomných."}, {"type": "choice", "label": "Dnes se zaměřím na  Vyberte jednu možnost.", "multi": false, "options": ["Srozumitelnost instrukce a první samostatný pokus", "Metodu, pomůcku nebo organizaci práce", "Ověření výsledku a reakci na zpětnou vazbu"]}, {"type": "text", "text": "Co se skutečně stalo", "heading": true}, {"type": "text", "text": "Zachyťte začátek, hlavní činnosti i závěr celé jednotky. Např. 10. min: učitel předvedl krok; dva žáci jej zopakovali bez pomoci.", "heading": false}, {"type": "table", "label": "Zachyťte začátek, hlavní činnosti i závěr celé jednotky. Např. 10. min: učitel předvedl krok; dva žáci jej zopakovali bez pomoci.", "rows": [["Čas", "Učitel udělal nebo řekl", "Žáci udělali nebo řekli"], ["", "", ""], ["", "", ""], ["", "", ""]]}, {"type": "text", "text": "Rozbor a moje reflexe", "heading": true}, {"type": "choice", "label": "Co ukázal výkon žáků  Vyberte jednu možnost.", "multi": false, "options": ["Postup zvládli samostatně a vysvětlili proč", "Postup zvládli po další ukázce nebo otázce", "Část skupiny potřebovala odlišnou podporu", "Z pozorování to zatím neumím rozhodnout"]}, {"type": "choice", "label": "O co svůj závěr opírám  Označte vše, co platí.", "multi": true, "options": ["Vlastní časový záznam nebo přesná odpověď žáka", "Anonymizovaná ukázka práce nebo výsledek úkolu", "Pozorování a komentář cvičného učitele", "Zatím nemám podklad a potřebuji jej doplnit"]}, {"type": "textarea", "label": "Kde podklad najdu\nČas situace, číslo přílohy nebo název záznamu v portfoliu."}, {"type": "textarea", "label": "Moje vysvětlení souvislosti\nVysvětlete: metoda pomohla tím, že… Dokládá to… Jiným vysvětlením může být…"}, {"type": "choice", "label": "Co si potřebuji ujasnit při rozboru  Označte vše, co platí.", "multi": true, "options": ["Proč učitel zvolil právě tento postup", "Podle čeho poznal porozumění nebo potřebu pomoci", "Co by šlo příště ověřit jinak", "Můj výklad už máme ověřený a plánujeme další krok"]}, {"type": "textarea", "label": "Domluva s cvičným učitelem nebo vyučujícím IVP\nPo rozboru doplňte pohled učitele a co jste si ověřili. Pokud rozbor neproběhl, uveďte to."}, {"type": "choice", "label": "Moje sebereflexe  Označte vše, co platí.", "multi": true, "options": ["Rozlišuji pozorování a vlastní výklad", "Propojuji postup učitele s reakcí žáků", "Potřebuji přesnější doklad nebo další pokus"]}, {"type": "choice", "label": "Při dalším náslechu ověřím  Vyberte jednu možnost.", "multi": false, "options": ["Co žák udělá po prvním zadání", "Co se změní po konkrétní zpětné vazbě", "Jak se ověří výsledek u každého žáka", "Jiný krok popsaný v mém záznamu"]}, {"type": "textarea", "label": "Vlastní upřesnění dalšího kroku\nVolitelně doplňte termín, situaci nebo otázku."}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "Vyplněný list uchovejte pro portfolio. V Ateliéru vyplňte záznam příslušného bloku a reflexi. Elektronické záznamy odevzdejte do Moodle podle zadání IVP. Pro řízenou diskusi vyberte jeden konkrétní okamžik.", "heading": false}]}, "ivp": {"id": "ivp", "title": "Mapa školy a první pozorování", "items": [{"type": "text", "text": "UPV · 2026/2027 · 1. ročník · 2. semestr (letní)", "heading": false}, {"type": "text", "text": "Mapa školy a první pozorování", "heading": true}, {"type": "text", "text": "Průběžná pedagogická praxe na IVP", "heading": false}, {"type": "text", "text": "K čemu list slouží  Zachytíte organizaci školy a jeden příklad propojení odborné teorie s praktickou činností žáků.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  Mapu při exkurzi, záznam při sledování zadané AV výuky. Mapu i rozbor pozorování připravte do diskuse na IVP.", "heading": false}, {"type": "text", "text": "Jak postupovat  Vyberte odpovídající možnosti a doplňte dohledatelné údaje. Textová pole využijte pro vlastní konkrétní postřeh.", "heading": false}, {"type": "input", "label": "Jméno studenta"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum a třída nebo skupina"}, {"type": "text", "text": "Moje mapa školy", "heading": true}, {"type": "textarea", "label": "Web školy a veřejný kontakt na vedení\nPoužijte pracovní kontakt zveřejněný školou."}, {"type": "textarea", "label": "Obor a školní vzdělávací program\nUveďte název oboru a odkaz nebo místo, kde najdete jeho ŠVP."}, {"type": "choice", "label": "Kde probíhá praktické vyučování  Označte vše, co platí.", "multi": true, "options": ["Ve školní dílně nebo odborné učebně", "Na smluvním pracovišti mimo školu", "Na více pracovištích podle zaměření", "Potřebuji si to ověřit"]}, {"type": "choice", "label": "Jak navazuje teorie na praxi  Vyberte jednu možnost.", "multi": false, "options": ["Učitel předem vysvětlí princip a žáci jej použijí", "Žáci nejprve řeší praktický úkol a pak jej vysvětlují", "Teorie a praktický nácvik se průběžně střídají", "Propojení jsem při této návštěvě nezachytil/a"]}, {"type": "textarea", "label": "Konkrétní příklad návaznosti\nDovednost, úkol a místo, kde ji žáci nacvičují."}, {"type": "text", "text": "Pozorování a podklad pro IVP", "heading": true}, {"type": "table", "label": "Pozorování a podklad pro IVP", "rows": [["Co učitel skutečně udělal nebo řekl", "Co bezprostředně udělali žáci"], ["", ""], ["", ""]]}, {"type": "choice", "label": "Proč si vybírám právě tuto situaci  Označte vše, co platí.", "multi": true, "options": ["Je na ní vidět propojení teorie s praxí", "Ukazuje rozdílné potřeby žáků", "Ukazuje užitečné ověření učení", "Nerozumím rozhodnutí učitele a chci je objasnit"]}, {"type": "textarea", "label": "Můj výklad situace\nVolitelně: myslím si…, protože jsem viděl/a… Zatím ale nevím…"}, {"type": "choice", "label": "Moje sebereflexe  Označte vše, co platí.", "multi": true, "options": ["Dokážu oddělit to, co jsem viděl/a, od svého vysvětlení", "Umím propojit učitelův postup s reakcí žáků", "Potřebuji přesnější doklad o tom, co žáci zvládli", "Potřebuji další pokus nebo konzultaci"]}, {"type": "choice", "label": "Otázka pro řízenou diskusi  Vyberte jednu možnost.", "multi": false, "options": ["Jak zvolená metoda souvisela s cílem hodiny?", "Podle čeho šlo poznat skutečné učení žáků?", "Jak by šla podpořit větší samostatnost žáků?", "Mám vlastní otázku uvedenou níže"]}, {"type": "textarea", "label": "Otázka nebo odpověď z diskuse\nVolitelně doplňte vlastní formulaci a co si chcete ověřit."}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "Mapu školy a pozorování uchovejte pro portfolio. V Ateliéru vyplňte záznam bloku a reflexi. Podklady přineste k řízené diskusi. IVP posuzuje účast, záznam a didaktické zdůvodnění; vyplnění listu samo o sobě není zápočet.", "heading": false}]}, "micro": {"id": "micro", "title": "Příprava mikrovýstupu", "items": [{"type": "text", "text": "UPV · 2026/2027 · 3. ročník · 5. semestr (zimní)", "heading": false}, {"type": "text", "text": "Příprava mikrovýstupu", "heading": true}, {"type": "text", "text": "Microteaching  •  Příprava a rozbor", "heading": false}, {"type": "text", "text": "K čemu list slouží  Připravíte krátkou instruktáž, při níž účastníci postup uvidí, sami zkusí a ověří výsledek.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  Přípravu před výstupem, rozbor po něm. Videomonitoring a práci se záznamem domluvte s vyučujícím podle sylabu.", "heading": false}, {"type": "text", "text": "Jak postupovat  Volby vám pomohou rozhodnout o vedení výuky. Doplňte vlastní cíl, postup a kritéria; prázdná šablona není hotová příprava.", "heading": false}, {"type": "input", "label": "Jméno studenta"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum a třída nebo skupina"}, {"type": "textarea", "label": "Téma a cíl mikrovýstupu\nPo mé instruktáži účastník samostatně… Úspěch poznám podle…"}, {"type": "choice", "label": "Jak zjistím výchozí zkušenost  Vyberte jednu možnost.", "multi": false, "options": ["Krátkou otázkou k předchozí práci", "Předvedením prvního kroku účastníkem", "Porovnáním dvou vzorků nebo řešení", "Jiným postupem uvedeným v přípravě"]}, {"type": "textarea", "label": "Co potřebují účastníci znát předem\nPředchozí dovednost a jak na ni navážete."}, {"type": "textarea", "label": "Pomůcky a příprava pracoviště\nCo bude k dispozici každému? Uveďte pravidlo bezpečné práce pro tento úkol."}, {"type": "choice", "label": "Forma prvního nácviku  Vyberte jednu možnost.", "multi": false, "options": ["Každý pracuje samostatně", "Dvojice se střídají v provedení a kontrole", "Malá skupina má rozdělené role"]}, {"type": "text", "text": "Rozsah odevzdávané vzorové přípravy podle metodiky 04 je nejméně dvě strany. Strany 1 a 2 tvoří osnovu přípravy; třetí strana slouží k následnému rozboru.", "heading": false}, {"type": "text", "text": "Můj plán instruktáže", "heading": true}, {"type": "textarea", "label": "První věta pro účastníky\nPojmenujte činnost a znak úspěchu, ne pouze téma."}, {"type": "table", "label": "Pracovní tabulka", "rows": [["Fáze a čas", "Co předvedu nebo řeknu", "Co udělají účastníci", "Jak ověřím výsledek"], ["Úvod", "", "", ""], ["Ukázka", "", "", ""], ["Samostatný pokus", "", "", ""], ["Závěr", "", "", ""]]}, {"type": "choice", "label": "Když se účastník zasekne  Označte vše, co platí.", "multi": true, "options": ["Nechám jej popsat, kde si není jistý", "Ukážu jen obtížný krok a vrátím mu činnost", "Nabídnu jiný vzorek nebo názornou pomůcku", "Nechám jej vysvětlit postup před dalším pokusem"]}, {"type": "textarea", "label": "Přesná otázka pro ověření porozumění\nNapříklad: podle čeho poznáte, že je výsledek přesný? Doplňte vlastní oborový příklad."}, {"type": "textarea", "label": "Co má vyučující při výstupu sledovat\nJedna situace pro cílenou zpětnou vazbu."}, {"type": "text", "text": "Rozbor mikrovýstupu", "heading": true}, {"type": "choice", "label": "Co účastníci po mé instrukci udělali  Označte vše, co platí.", "multi": true, "options": ["Začali samostatně správným krokem", "Zeptali se na zadání nebo kritérium", "Zvolili rozdílné postupy", "Potřebovali opakovat ukázku"]}, {"type": "choice", "label": "O co svůj závěr opírám  Označte vše, co platí.", "multi": true, "options": ["Vlastní časový záznam nebo přesná odpověď žáka", "Anonymizovaná ukázka práce nebo výsledek úkolu", "Pozorování a komentář cvičného učitele", "Zatím nemám podklad a potřebuji jej doplnit"]}, {"type": "textarea", "label": "Kde podklad najdu\nČas situace, číslo přílohy nebo název záznamu v portfoliu."}, {"type": "choice", "label": "Moje sebereflexe  Označte vše, co platí.", "multi": true, "options": ["Pojmenoval/a jsem cíl a znak úspěchu", "Má ukázka i slovní projev byly srozumitelné", "Všiml/a jsem si reakce a upravil/a podporu", "Potřebuji zpřesnit pokyn, gesto nebo ověření"]}, {"type": "textarea", "label": "Zpětná vazba vyučujícího a účastníků\nVolitelně připište konkrétní okamžik. Pokud rozbor teprve proběhne, nechte pole volné."}, {"type": "choice", "label": "Pro druhý pokus upravím  Vyberte jednu možnost.", "multi": false, "options": ["První větu a cíl", "Pořadí nebo tempo ukázky", "Prostor pro samostatnou práci", "Způsob ověření výsledku"]}, {"type": "textarea", "label": "Nové znění nebo nový postup\nVolitelně doplňte konkrétní úpravu a jak poznáte její účinek."}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "Dopracujte alespoň dvoustránkovou vzorovou přípravu a nahrajte ji do Moodle podle zadání IVP. V Ateliéru vyplňte sebereflexi a rozbor. Domácí nácvik pomáhá s přípravou; předepsaný mikrovýstup a rozbor na IVP tím nejsou nahrazeny.", "heading": false}]}, "kurzy": {"id": "kurzy", "title": "Přenos poznatku do výuky", "items": [{"type": "text", "text": "AKADEMICKÝ ROK 2026/2027", "heading": false}, {"type": "text", "text": "Přenos poznatku do výuky", "heading": true}, {"type": "text", "text": "Kurzy ČZU  •  Plán a vyhodnocení profesního rozvoje", "heading": false}, {"type": "text", "text": "K čemu list slouží  Vyberete poznatek z kurzu nebo studijního zdroje a ověříte jeho přínos při konkrétním vedení žáka.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  Plán vyplňte po studiu zdroje. Druhou stranu až po skutečném vyzkoušení.", "heading": false}, {"type": "text", "text": "Jak postupovat  Vyberte oblast, naplánujte jedinou změnu a určete doklad o jejím účinku. Vlastní poznámky mohou být krátké.", "heading": false}, {"type": "input", "label": "Jméno studenta"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum a třída nebo skupina"}, {"type": "textarea", "label": "Kurz nebo zdroj\nNázev, poskytovatel nebo autor a odkaz. Nejde o přihlášku do kurzu."}, {"type": "choice", "label": "Chci zlepšit  Vyberte jednu možnost.", "multi": false, "options": ["Srozumitelné předání úkolu", "Rozpoznání samostatnosti žáka", "Zpětnou vazbu po výkonu"]}, {"type": "choice", "label": "Nový postup použiji při  Vyberte jednu možnost.", "multi": false, "options": ["Zadání pracovního úkolu", "Názorné ukázce a prvním pokusu", "Samostatné činnosti žáka", "Rozboru a plánování dalšího pokusu"]}, {"type": "textarea", "label": "Co změním oproti svému dosavadnímu postupu\nJedna věta nebo odkaz na konkrétní materiál ze zdroje."}, {"type": "textarea", "label": "Příležitost k vyzkoušení\nÚkol, skupina a termín. Kdo může průběh pozorovat?"}, {"type": "choice", "label": "Přínos poznám podle toho, že žák  Označte vše, co platí.", "multi": true, "options": ["Vlastními slovy vysvětlí zadání", "Začne bez dalšího opakování pokynu", "Zdůvodní samostatnou volbu postupu", "Upraví práci podle zpětné vazby"]}, {"type": "text", "text": "Co ukázalo vyzkoušení", "heading": true}, {"type": "choice", "label": "Stav mého pokusu  Vyberte jednu možnost.", "multi": false, "options": ["Postup jsem použil/a a mám doklad", "Postup jsem použil/a, ale účinek je nejasný", "Ještě čekám na vhodnou příležitost"]}, {"type": "textarea", "label": "Co jsem udělal/a a jak reagoval žák\nKrátký faktický záznam nebo odkaz na anonymizovaný podklad. Pokud pokus neproběhl, nevyplňujte výsledek."}, {"type": "choice", "label": "Moje reflexe  Vyberte jednu možnost.", "multi": false, "options": ["Postup pomohl a chci jej opakovaně ověřit", "Pomohl jen části žáků a potřebuji úpravu", "Přínos zatím nedokážu rozlišit", "Postup neodpovídal situaci a zvolím jiný"]}, {"type": "textarea", "label": "Zpětná vazba cvičného učitele nebo IVP\nVolitelně doplňte jeho postřeh a vlastní závěr."}, {"type": "choice", "label": "Můj další krok  Vyberte jednu možnost.", "multi": false, "options": ["Ponechám postup a ověřím jej s jiným úkolem", "Zjednoduším instrukci nebo pomůcku", "Změním okamžik, kdy postup použiji", "Proberu vhodnost postupu s vyučujícím IVP"]}, {"type": "textarea", "label": "Vlastní upřesnění\nVolitelně: kdy a podle čeho vyhodnotím další pokus."}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "Plán i vyhodnocení uchovejte pro portfolio. V Ateliéru vyplňte reflexi v modulu Kurzy ČZU. Případné potvrzení účasti přiložte zvlášť. Tento pracovní list není certifikát ani doklad o absolvování kurzu.", "heading": false}]}, "continuous": {"id": "continuous", "title": "Příprava vlastní výuky", "items": [{"type": "text", "text": "UPV · 2026/2027 · 3. ročník · 6. semestr (letní)", "heading": false}, {"type": "text", "text": "Příprava vlastní výuky", "heading": true}, {"type": "text", "text": "Souvislá řízená pedagogická praxe", "heading": false}, {"type": "text", "text": "K čemu list slouží  Naplánujete jednu vyučovací jednotku, zaznamenáte její účinek a využijete doporučení cvičného učitele v dalším výstupu.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  Běžnou přípravu konzultujte předem; závěrečný výstup připravte samostatně. Rozbor doplňte po odučení.", "heading": false}, {"type": "text", "text": "Jak postupovat  Tento list použijte opakovaně pro každý výstup. Uveďte vlastní cíl, průběh a konkrétní doklad o učení.", "heading": false}, {"type": "input", "label": "Jméno studenta"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum a třída nebo skupina"}, {"type": "textarea", "label": "Číslo výstupu a téma\nDoplňte předmět, délku jednotky a návaznost na předchozí práci žáků."}, {"type": "textarea", "label": "Co má žák na konci samostatně zvládnout\nUveďte činnost a pozorovatelný znak úspěchu."}, {"type": "choice", "label": "Podpora žáků v této hodině  Označte vše, co platí.", "multi": true, "options": ["Názorná ukázka a společný první krok", "Více času nebo rozdělení úkolu na menší části", "Samostatná práce s průběžným ověřením", "Navazující náročnější úkol pro rychlejší žáky"]}, {"type": "table", "label": "Podpora žáků v této hodině  Označte vše, co platí.", "rows": [["Fáze a čas", "Moje činnost", "Činnost žáků", "Doklad o učení"], ["Úvod", "", "", ""], ["Hlavní část", "", "", ""], ["Závěr", "", "", ""]]}, {"type": "textarea", "label": "Pomůcky a bezpečnost práce\nCo připravím a co před činností ověřím?"}, {"type": "textarea", "label": "Domluva s cvičným učitelem\nNa kterou situaci zaměří pozorování? Kdy přípravu společně probereme?"}, {"type": "text", "text": "Rozbor výstupu a další krok", "heading": true}, {"type": "choice", "label": "Co po hodině mohu doložit  Vyberte jednu možnost.", "multi": false, "options": ["Žáci dosáhli cíle samostatně", "Cíle dosáhli s přiměřenou podporou", "Část žáků potřebuje navazující nácvik", "Chybí mi průkazné ověření výsledku"]}, {"type": "choice", "label": "O co svůj závěr opírám  Označte vše, co platí.", "multi": true, "options": ["Vlastní časový záznam nebo přesná odpověď žáka", "Anonymizovaná ukázka práce nebo výsledek úkolu", "Pozorování a komentář cvičného učitele", "Zatím nemám podklad a potřebuji jej doplnit"]}, {"type": "textarea", "label": "Kde podklad najdu\nČas situace, číslo přílohy nebo název záznamu v portfoliu."}, {"type": "textarea", "label": "Rozhodující okamžik\nStručně nebo odkazem na podklad: co žáci dělali, co jsem změnil/a a co následovalo."}, {"type": "choice", "label": "Moje sebereflexe  Označte vše, co platí.", "multi": true, "options": ["Můj postup podpořil samostatnost žáků", "Včas jsem zachytil/a rozdílné potřeby", "Dokážu vysvětlit změnu svého postupu", "Potřebuji lépe ověřovat porozumění"]}, {"type": "textarea", "label": "Doporučení cvičného učitele\nDoplňte až po rozhovoru; nepředvyplňujte za učitele hodnocení."}, {"type": "choice", "label": "V další přípravě upravím  Vyberte jednu možnost.", "multi": false, "options": ["Cíl a kritéria úspěchu", "Instrukci nebo názornou ukázku", "Organizaci a čas pro žáky", "Ověření učení a zpětnou vazbu"]}, {"type": "textarea", "label": "Můj další pokus\nVolitelně doplňte situaci, termín a znak účinku."}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "Přípravu a doporučení uchovejte pro portfolio; v Ateliéru vyplňte záznam výstupu a reflexi. Rozvrh výstupů předejte koordinátorovi a pedagogovi IVP do 3 dnů od zahájení praxe. V den závěrečného výstupu předložte portfolio; elektronickou verzi odevzdejte do Moodle podle zadání.", "heading": false}, {"type": "text", "text": "Metodika 05: standardně 4 týdny a 14 výstupů, navíc závěrečný samostatný výstup před komisí. Varianta 2 týdny a 8 výstupů vyžaduje souhlas ředitele IVP a doložení dvouletého pedagogického působení na odborné škole.", "heading": false}]}, "nacvik": {"id": "nacvik", "title": "Rozbor modelové situace", "items": [{"type": "text", "text": "AKADEMICKÝ ROK 2026/2027", "heading": false}, {"type": "text", "text": "Rozbor modelové situace", "heading": true}, {"type": "text", "text": "Praxe nanečisto", "heading": false}, {"type": "text", "text": "K čemu list slouží  Vyzkoušíte si rozhodnutí v bezpečném modelu a připravíte jeden postup pro skutečnou výuku.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  Před volbou v trenažéru si označte očekávání. Po zobrazení odezvy vyplňte druhou stranu.", "heading": false}, {"type": "text", "text": "Jak postupovat  Vyberte scénář a svůj záměr. Vlastní formulaci můžete doplnit; modelový výsledek nevydávejte za skutečné pozorování žáků.", "heading": false}, {"type": "input", "label": "Jméno studenta"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum a třída nebo skupina"}, {"type": "choice", "label": "Můj scénář  Vyberte jednu možnost.", "multi": false, "options": ["Jak začít instruktáž", "Dvě dvojice se zasekly", "Co říct při rozboru"]}, {"type": "choice", "label": "Nejdříve potřebuji zjistit  Označte vše, co platí.", "multi": true, "options": ["Co mají žáci na konci samostatně zvládnout", "Kterému kroku žáci nerozumějí", "Co se po zpětné vazbě změnilo", "Jaký doklad podporuje můj výklad"]}, {"type": "choice", "label": "Můj první krok  Vyberte jednu možnost.", "multi": false, "options": ["Pojmenuji činnost a znak úspěchu", "Nechám žáka popsat, kde se zastavil", "Ukážu jen obtížnou část a vrátím mu úkol", "Zeptám se na důvod učitelova rozhodnutí"]}, {"type": "textarea", "label": "Vlastní formulace\nVolitelně napište přesná první slova nebo odkaz na svou volbu v trenažéru."}, {"type": "choice", "label": "Jakou reakci očekávám  Vyberte jednu možnost.", "multi": false, "options": ["Žák začne samostatně správným krokem", "Žák pojmenuje potíž nebo svou volbu", "Žák použije zpětnou vazbu v dalším pokusu", "Získám informaci, která mi dosud chybí"]}, {"type": "text", "text": "Co si z nácviku přenesu do praxe", "heading": true}, {"type": "choice", "label": "Co mi ukázala odezva modelu  Označte vše, co platí.", "multi": true, "options": ["Zadání ještě nevyjadřovalo výsledek žáka", "Pomoc mohla zbytečně převzít žákovu práci", "Chyběl konkrétní doklad o účinku", "Zvolený postup odpovídá cíli situace", "Potřebuji porovnat další variantu"]}, {"type": "textarea", "label": "Moje reflexe\nVolitelně: ponechám…, upravím…, ověřím si…"}, {"type": "choice", "label": "Moje sebereflexe  Označte vše, co platí.", "multi": true, "options": ["Dokážu vysvětlit svou volbu", "Dokážu nabídnout jiný postup", "Rozlišuji odezvu modelu od skutečné praxe", "Potřebuji rozhodnutí konzultovat"]}, {"type": "choice", "label": "Další krok  Vyberte jednu možnost.", "multi": false, "options": ["Zkusím jinou možnost v trenažéru", "Připravím jednu otázku pro cvičného učitele", "Použiji postup v domluveném vlastním výstupu", "Nejdříve si všimnu podobné situace při náslechu"]}, {"type": "textarea", "label": "Vlastní upřesnění a otázka pro IVP\nVolitelně doplňte, kde změnu ověříte a podle čeho poznáte účinek."}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "List uchovejte pro portfolio. V Ateliéru vyplňte navazující reflexi v Praxi nanečisto. Při skutečné praxi založte nový záznam a porovnejte očekávání s reálnou reakcí žáků. Nácvik sám nenahrazuje povinnou praxi ani potvrzení kompetence.", "heading": false}]}, "guided": {"id": "guided", "title": "Řízená náslechová praxe", "items": [{"type": "text", "text": "UPV · 2026/2027 · 2. ročník · 4. semestr (letní)", "heading": false}, {"type": "text", "text": "Řízená náslechová praxe", "heading": true}, {"type": "text", "text": "Záznam jedné výukové jednotky a její rozbor", "heading": false}, {"type": "text", "text": "K čemu list slouží  V odborné výuce prověříte vztah mezi cílem, metodou a tím, co konkrétně zvládli žáci.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  Před hodinou doplňte údaje a zaměření. Během celé jednotky zapisujte průběh. Po ní doplňte rozbor.", "heading": false}, {"type": "text", "text": "Jak postupovat  Volby jsou pomůcka. Ke každému závěru doplňte konkrétní situaci, reakci žáků a vlastní vysvětlení.", "heading": false}, {"type": "input", "label": "Jméno studenta"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum a třída nebo skupina"}, {"type": "choice", "label": "Druh jednotky  Vyberte jednu možnost.", "multi": false, "options": ["Teoretická výuka", "Odborný výcvik nebo odborná praxe"]}, {"type": "text", "text": "Rozsah: 10 teoretických + 2 praktické náslechy během dvou týdnů na předem schválené škole. Pro každou jednotku vyplňte vlastní arch; student rozsah nepřepíná.", "heading": false}, {"type": "textarea", "label": "Téma a očekávaný výsledek žáka\nCo má žák vysvětlit, provést nebo posoudit? Doplňte počet přítomných."}, {"type": "choice", "label": "Dnes se zaměřím na  Vyberte jednu možnost.", "multi": false, "options": ["Srozumitelnost instrukce a první samostatný pokus", "Metodu, pomůcku nebo organizaci práce", "Ověření výsledku a reakci na zpětnou vazbu"]}, {"type": "text", "text": "Co se skutečně stalo", "heading": true}, {"type": "text", "text": "Zachyťte začátek, hlavní činnosti i závěr celé jednotky. Např. 10. min: učitel předvedl krok; dva žáci jej zopakovali bez pomoci.", "heading": false}, {"type": "table", "label": "Zachyťte začátek, hlavní činnosti i závěr celé jednotky. Např. 10. min: učitel předvedl krok; dva žáci jej zopakovali bez pomoci.", "rows": [["Čas", "Učitel udělal nebo řekl", "Žáci udělali nebo řekli"], ["", "", ""], ["", "", ""], ["", "", ""]]}, {"type": "text", "text": "Rozbor a moje reflexe", "heading": true}, {"type": "choice", "label": "Co ukázal výkon žáků  Vyberte jednu možnost.", "multi": false, "options": ["Postup zvládli samostatně a vysvětlili proč", "Postup zvládli po další ukázce nebo otázce", "Část skupiny potřebovala odlišnou podporu", "Z pozorování to zatím neumím rozhodnout"]}, {"type": "choice", "label": "O co svůj závěr opírám  Označte vše, co platí.", "multi": true, "options": ["Vlastní časový záznam nebo přesná odpověď žáka", "Anonymizovaná ukázka práce nebo výsledek úkolu", "Pozorování a komentář cvičného učitele", "Zatím nemám podklad a potřebuji jej doplnit"]}, {"type": "textarea", "label": "Kde podklad najdu\nČas situace, číslo přílohy nebo název záznamu v portfoliu."}, {"type": "textarea", "label": "Moje vysvětlení souvislosti\nVysvětlete: metoda pomohla tím, že… Dokládá to… Jiným vysvětlením může být…"}, {"type": "choice", "label": "Co si potřebuji ujasnit při rozboru  Označte vše, co platí.", "multi": true, "options": ["Proč učitel zvolil právě tento postup", "Podle čeho poznal porozumění nebo potřebu pomoci", "Co by šlo příště ověřit jinak", "Můj výklad už máme ověřený a plánujeme další krok"]}, {"type": "textarea", "label": "Domluva s cvičným učitelem nebo vyučujícím IVP\nPo rozboru doplňte pohled učitele a co jste si ověřili. Pokud rozbor neproběhl, uveďte to."}, {"type": "choice", "label": "Moje sebereflexe  Označte vše, co platí.", "multi": true, "options": ["Rozlišuji pozorování a vlastní výklad", "Propojuji postup učitele s reakcí žáků", "Potřebuji přesnější doklad nebo další pokus"]}, {"type": "choice", "label": "Při dalším náslechu ověřím  Vyberte jednu možnost.", "multi": false, "options": ["Co žák udělá po prvním zadání", "Co se změní po konkrétní zpětné vazbě", "Jak se ověří výsledek u každého žáka", "Jiný krok popsaný v mém záznamu"]}, {"type": "textarea", "label": "Vlastní upřesnění dalšího kroku\nVolitelně doplňte termín, situaci nebo otázku."}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "Vyplněný list uchovejte pro portfolio. V Ateliéru vyplňte záznam příslušného bloku a reflexi. Elektronické záznamy odevzdejte do Moodle podle zadání IVP. Pro řízenou diskusi vyberte jeden konkrétní okamžik.", "heading": false}]}, "ss": {"id": "ss", "title": "Předání výsledku z pracoviště škole", "items": [{"type": "text", "text": "AKADEMICKÝ ROK 2026/2027", "heading": false}, {"type": "text", "text": "Předání výsledku z pracoviště škole", "heading": true}, {"type": "text", "text": "Praxe SŠ  •  Jeden pracovní úkol", "heading": false}, {"type": "text", "text": "K čemu list slouží  Propojíte zadání školy, vedení instruktora a samostatný výkon žáka. Vytvoříte srozumitelný podklad pro navazující výuku.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  Před úkolem domluvte výsledek a kritérium. Po výkonu a rozboru doplňte zjištění.", "heading": false}, {"type": "text", "text": "Jak postupovat  Pracujte s modelovým měřením dvou vzorků nebo vlastním oborovým úkolem. U žáka použijte anonymní označení.", "heading": false}, {"type": "input", "label": "Jméno studenta"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum a třída nebo skupina"}, {"type": "textarea", "label": "Pracovní úkol a anonymní označení žáka\nNapříklad žák A; bez jména a osobních údajů."}, {"type": "choice", "label": "Dohodnutý výsledek  Označte vše, co platí.", "multi": true, "options": ["Žák samostatně zvolí vhodnou pomůcku", "Žák bezpečně provede pracovní postup", "Žák ověří výsledek podle kritéria", "Žák vysvětlí a zdůvodní svou volbu"]}, {"type": "textarea", "label": "Kritérium školy a pracoviště\nCo přesně musí být u tohoto úkolu splněno?"}, {"type": "choice", "label": "Co udělá instruktor  Označte vše, co platí.", "multi": true, "options": ["Předvede první vzorek nebo klíčový krok", "Ověří porozumění zadání", "Ponechá další pokus žákovi", "Zachytí podporu, kterou žák potřeboval"]}, {"type": "choice", "label": "Co sleduji u žáka  Označte vše, co platí.", "multi": true, "options": ["Volbu postupu a její zdůvodnění", "Samostatnost při provádění", "Kontrolu a opravu výsledku", "Použití zpětné vazby v dalším pokusu"]}, {"type": "textarea", "label": "Co potřebujeme domluvit předem\nVolitelně doplňte, kdo bude výkon sledovat a kdo podklad převezme."}, {"type": "text", "text": "Co předám škole a proč", "heading": true}, {"type": "choice", "label": "Pozorovaný výkon  Vyberte jednu možnost.", "multi": false, "options": ["Žák zvládl úkol samostatně", "Žák zvládl úkol po upřesnění zadání", "Žák potřeboval opakovanou ukázku", "Úkol je třeba znovu nacvičit"]}, {"type": "choice", "label": "O co svůj závěr opírám  Označte vše, co platí.", "multi": true, "options": ["Vlastní časový záznam nebo přesná odpověď žáka", "Anonymizovaná ukázka práce nebo výsledek úkolu", "Pozorování a komentář cvičného učitele", "Zatím nemám podklad a potřebuji jej doplnit"]}, {"type": "textarea", "label": "Kde podklad najdu\nČas situace, číslo přílohy nebo název záznamu v portfoliu."}, {"type": "textarea", "label": "Stručná zpráva škole\nUveďte úkol, kritérium, míru podpory a další krok. Lze odkázat na přiložený záznam."}, {"type": "choice", "label": "Moje reflexe  Označte vše, co platí.", "multi": true, "options": ["Výrobek sám neukazuje celý postup žáka", "Pozorování odhalilo místo potřebné podpory", "Kritérium jsme potřebovali vyjasnit", "Navazující úkol má ověřit větší samostatnost"]}, {"type": "textarea", "label": "Co do zprávy doplním po zpětné vazbě\nVolitelně zapište otázku školy, instruktora nebo IVP."}, {"type": "choice", "label": "Navazující úkol  Vyberte jednu možnost.", "multi": false, "options": ["Stejný postup s menší podporou", "Nový vzorek nebo situace se stejným principem", "Opakování konkrétního obtížného kroku", "Samostatná kontrola a vysvětlení výsledku"]}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "Podklad uchovejte pro portfolio. V Ateliéru vyplňte reflexi v Praxi SŠ. S instruktorem a školou potvrďte obsah předání a navazující úkol. List podporuje rozbor praxe; není sám o sobě oficiálním hodnocením žáka ani potvrzením absolvování.", "heading": false}]}, "reflection": {"id": "reflection", "title": "Reflexe pedagogické praxe", "items": [{"type": "text", "text": "UPV · 2026/2027 · 3. ročník · 6. semestr (letní)", "heading": false}, {"type": "text", "text": "Reflexe pedagogické praxe", "heading": true}, {"type": "text", "text": "Osnova závěrečného zhodnocení", "heading": false}, {"type": "text", "text": "K čemu list slouží  Porovnáte doklady z náslechu a vlastní výuky a popíšete, jak se mění vaše učitelské rozhodování.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  Na závěr praxí před řízenou diskusí a odevzdáním do Moodle.", "heading": false}, {"type": "text", "text": "Jak postupovat  Začněte výběrem možností. U každé části připojte konkrétní doklad; krátké poznámky rozpracujte do vlastního zhodnocení.", "heading": false}, {"type": "input", "label": "Jméno studenta"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum a třída nebo skupina"}, {"type": "text", "text": "Metodika 06 požaduje komplexní zhodnocení praxí nejméně na třech stranách. Tato třístránková osnova vám pomůže s obsahem; samotné zaškrtnutí voleb a prázdné řádky požadavek nesplňují. Závazné podmínky pro rok 2026/2027 ověřte v Moodle předmětu.", "heading": false}, {"type": "choice", "label": "Porovnávám svůj rozvoj v oblasti  Vyberte jednu možnost.", "multi": false, "options": ["Plánování a srozumitelnost výuky", "Podpory samostatnosti a bezpečného učení", "Ověřování výsledků a zpětné vazby", "Reflexe a spolupráce s cvičným učitelem"]}, {"type": "text", "text": "Dva doklady z portfolia", "heading": true}, {"type": "textarea", "label": "Dřívější náslech\nNázev a datum záznamu, činnost učitele a konkrétní reakce žáků."}, {"type": "textarea", "label": "Pozdější vlastní výstup\nNázev a datum záznamu, moje rozhodnutí a konkrétní reakce žáků."}, {"type": "text", "text": "Co se změnilo v mém uvažování", "heading": true}, {"type": "choice", "label": "Změnu vidím hlavně v tom, že  Označte vše, co platí.", "multi": true, "options": ["Předem vymezuji výsledek, který lze pozorovat", "Více sleduji práci žáků než vlastní výkon", "Dávám žákům více prostoru pro rozhodování", "Upravuji výuku podle skutečného porozumění", "Své hodnocení opírám o konkrétní podklady"]}, {"type": "textarea", "label": "Jak se změna projevila\nPorovnejte oba doklady. Pomůže začátek: dříve jsem…, při vlastním výstupu jsem…, reakce žáků ukázala…"}, {"type": "choice", "label": "Co zatím nemám dostatečně doložené  Označte vše, co platí.", "multi": true, "options": ["Účinek opakovaného použití stejné změny", "Učení žáků s rozdílnou potřebou podpory", "Samostatnost po odebrání pomoci", "Přenos dovednosti do nového úkolu", "Mám jinou oblast uvedenou níže"]}, {"type": "textarea", "label": "Co mi chybí a jak to zjistím\nPojmenujte potřebný doklad a příležitost, kdy jej získáte."}, {"type": "text", "text": "Další profesní rozvoj a rozbor na IVP", "heading": true}, {"type": "choice", "label": "V nejbližším pokusu se zaměřím na  Vyberte jednu možnost.", "multi": false, "options": ["Přesnější zadání a kritéria", "Otázky, které odhalí porozumění", "Podporu žáka bez převzetí jeho práce", "Zpětnou vazbu, kterou žák hned použije", "Jiný konkrétní krok uvedený v mém plánu"]}, {"type": "textarea", "label": "Můj plán dalšího pokusu\nSituace nebo úkol, jedna změna, termín a doklad, podle kterého poznám účinek."}, {"type": "textarea", "label": "Podnět z rozboru na IVP\nCo v mém pohledu upřesnila otázka nebo zpětná vazba vyučujícího?"}, {"type": "textarea", "label": "Silná stránka a potřebná podpora\nKterou svou schopnost umím doložit? S čím se obrátím na cvičného učitele nebo IVP?"}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "Dopracujte vlastní souvislé zhodnocení podle zadání, připojte odkazy na vybrané doklady a odevzdejte je do Moodle. Připravte se vysvětlit své rozhodnutí při řízené diskusi.", "heading": false}, {"type": "choice", "label": "Před uložením zkontroluji  Označte vše, co platí.", "multi": true, "options": ["Mám srovnatelné a anonymizované doklady", "Vysvětluji změnu i její hranice", "Mám konkrétní plán dalšího rozvoje", "Splňuji rozsah a zadání pro 2026/2027"]}]}, "adaptio": {"id": "adaptio", "title": "Rozhovor s mentorem", "items": [{"type": "text", "text": "AKADEMICKÝ ROK 2026/2027", "heading": false}, {"type": "text", "text": "Rozhovor s mentorem", "heading": true}, {"type": "text", "text": "Adaptio  •  Podpora při vstupu do školy a do výuky", "heading": false}, {"type": "text", "text": "K čemu list slouží  Připravíte konkrétní otázku pro cvičného učitele či mentora a zachytíte dohodnutou podporu.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  První stranu před setkáním; druhou po rozhovoru a při ověření domluvy.", "heading": false}, {"type": "text", "text": "Jak postupovat  Vyberte situaci a napište vlastní otázku. Po rozhovoru doplňte kdo, co a do kdy udělá. Nejde o další povinný blok praxe.", "heading": false}, {"type": "input", "label": "Jméno studenta"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum a třída nebo skupina"}, {"type": "choice", "label": "S čím přicházím  Vyberte jednu možnost.", "multi": false, "options": ["Přicházím do nové školy", "Připravuji první vlastní hodinu", "Hodina mě zaskočila"]}, {"type": "choice", "label": "S kým budu mluvit  Vyberte jednu možnost.", "multi": false, "options": ["S cvičným učitelem", "S mentorem na pracovišti", "S vyučujícím IVP", "S koordinátorem o organizaci praxe"]}, {"type": "choice", "label": "Co potřebuji  Označte vše, co platí.", "multi": true, "options": ["Vyjasnit pravidla, kontakt nebo organizaci návštěvy", "Probrat přípravu a přiměřený cíl", "Domluvit, čeho si mentor při výuce všimne", "Porozumět konkrétní náročné situaci", "Domluvit míru podpory a další pokus"]}, {"type": "textarea", "label": "Situace a termín rozhovoru\nVolitelně popište jeden okamžik a kdy jej chcete probrat."}, {"type": "choice", "label": "Otázka, kterou si vezmu s sebou  Vyberte jednu možnost.", "multi": false, "options": ["Co si potřebuji připravit před první návštěvou?", "Kterou část mé instruktáže má smysl upravit?", "Podle čeho poznám, kdy žák potřebuje podporu?", "Jak mohu příště postupovat jinak?", "Mám vlastní otázku v poznámce"]}, {"type": "text", "text": "Domluva a moje reflexe", "heading": true}, {"type": "choice", "label": "Co rozhovor přinesl  Označte vše, co platí.", "multi": true, "options": ["Mám jasnější představu o své roli", "Vím, co mohu vyzkoušet samostatně", "Mám domluvenou konkrétní podporu", "Potřebuji ještě další setkání"]}, {"type": "textarea", "label": "Co jsme si skutečně domluvili\nKdo udělá co a do kdy? Nevyplňujte tuto část před rozhovorem."}, {"type": "choice", "label": "Co mohu udělat sám nebo sama  Označte vše, co platí.", "multi": true, "options": ["Připravit pracoviště a pomůcky", "Upravit cíl a instrukci", "Vyzkoušet domluvenou část výuky", "Zachytit situaci a podklad pro rozbor", "Potřebuji podporu u všech domluvených kroků"]}, {"type": "textarea", "label": "Moje sebereflexe\nVolitelně: po rozhovoru rozumím…, jistotu mi dává…, ještě potřebuji…"}, {"type": "choice", "label": "Jak poznáme, že domluva pomohla  Vyberte jednu možnost.", "multi": false, "options": ["Návštěva proběhne podle vyjasněného plánu", "Žáci porozumí upravené instrukci", "Zvládnu domluvený krok s menší podporou", "Při dalším rozboru porovnáme konkrétní doklady"]}, {"type": "textarea", "label": "Termín ověření a vlastní poznámka\nVolitelně doplňte datum nebo návaznou situaci."}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "List uchovejte pro portfolio. V Ateliéru vyplňte reflexi rozhovoru v Adaptio. Organizační nejasnost řešte s koordinátorem, výukovou situaci s cvičným učitelem nebo IVP. Zápis nic automaticky neodesílá.", "heading": false}]}, "rozbor-cvicny-ucitel": {"id": "rozbor-cvicny-ucitel", "title": "Rozbor vyučovací jednotky", "items": [{"type": "text", "text": "AKADEMICKÝ ROK 2026/2027", "heading": false}, {"type": "text", "text": "Rozbor vyučovací jednotky", "heading": true}, {"type": "text", "text": "Podklad pro cvičného učitele a společnou zpětnou vazbu", "heading": false}, {"type": "text", "text": "K čemu list slouží  Pomůže cvičnému učiteli posoudit studentovu výuku a domluvit s ním konkrétní další krok. Nejde o automatické potvrzení zápočtu.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  Při hospitaci a následném rozhovoru se studentem IVP.", "heading": false}, {"type": "text", "text": "Jak postupovat  Cvičný učitel u každé oblasti označí jednu odpověď. K významným zjištěním připojí příklad. Student doplní vlastní reakci v závěru.", "heading": false}, {"type": "input", "label": "Student IVP a cvičný učitel"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum a číslo jednotky"}, {"type": "input", "label": "Předmět a tematický celek"}, {"type": "input", "label": "Téma hodiny"}, {"type": "input", "label": "Ročník, třída nebo skupina a počet žáků"}, {"type": "choice", "label": "Posuzuji  Vyberte jednu možnost.", "multi": false, "options": ["Teoretickou vyučovací jednotku", "Praktickou vyučovací jednotku"]}, {"type": "text", "text": "ANO = doloženo v pozorované hodině; ČÁSTEČNĚ = projevilo se jen v části situací; NE = sledovaný znak se neprojevil; NEPOSUZOVÁNO = nemám podklady. Neposuzováno není neúspěch.", "heading": false}, {"type": "textarea", "label": "Domluvené zaměření hospitace\nCo chce student v této hodině ověřit?"}, {"type": "text", "text": "Pozorované oblasti výuky", "heading": true}, {"type": "text", "text": "V každém řádku označte jednu možnost. Zjištění opřete o konkrétní situaci v posledním sloupci. Vlastní poznámky můžete rozšířit ve Wordu.", "heading": false}, {"type": "table", "label": "V každém řádku označte jednu možnost. Zjištění opřete o konkrétní situaci v posledním sloupci. Vlastní poznámky můžete rozšířit ve Wordu.", "rows": [["Oblast", "Posouzení", "Konkrétní příklad nebo otázka"], ["Srozumitelný úvod a struktura jednotky", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Vzdělávací cíle formulované jako činnost žáka", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Výchovné cíle a pracovní návyky v průběhu výuky", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Vhodná forma a metody ve vztahu k cíli", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Účelné využití pomůcek a didaktické techniky", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Mezipředmětové vztahy a průřezová témata podle ŠVP", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Motivace a aktivizace žáků během jednotky", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""]]}, {"type": "text", "text": "Specifika jednotky a komunikace", "heading": true}, {"type": "table", "label": "Specifika jednotky a komunikace", "rows": [["Oblast", "Posouzení", "Konkrétní příklad nebo otázka"], ["Teorie: připravené otázky k výkladu a opakování", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Praxe: srozumitelná instruktáž a dostatek samostatné práce žáků", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Praxe: průběžná kontrola žáků po instruktáži", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Praxe: bezpečnost, organizace a čas na úklid", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Zhodnocení průběhu a výsledku na závěr", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Verbální projev: hlasitost, intonace, srozumitelnost a jazyk", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""], ["Neverbální projev: gesta, mimika, pohyb a oční kontakt", "  Ano\n  Částečně\n  Ne\n  Neposuzováno", ""]]}, {"type": "text", "text": "U specifik druhého typu výuky označte Neposuzováno. V praktické jednotce sledujte prostor pro samostatnou práci; původní metodika doporučuje nejméně polovinu času. Vztahujte posouzení ke konkrétnímu cíli a podmínkám.", "heading": false}, {"type": "text", "text": "Společný závěr rozboru", "heading": true}, {"type": "text", "text": "Jak rozhovor vést", "heading": true}, {"type": "text", "text": "Začněte studentovou sebereflexí, poté pojmenujte doloženou silnou stránku. Vyberte jednu změnu, kterou lze uskutečnit při dalším výstupu. Pojmy a příklady cílů najdete v manuálu rozboru.", "heading": false}, {"type": "textarea", "label": "Co se podařilo a čím je to doloženo\nVyplňuje cvičný učitel. Popište činnost studenta i reakci žáků."}, {"type": "choice", "label": "Doporučené zaměření dalšího výstupu  Označte vše, co platí.", "multi": true, "options": ["Upřesnit cíl a znak úspěchu", "Rozdělit instruktáž do kroků", "Posílit činnost žáků", "Ověřit porozumění nebo provedení", "Zlepšit organizaci a komunikaci", "Jiný krok podle rozboru"]}, {"type": "textarea", "label": "Konkrétní doporučení\nCo má student udělat jinak a podle čeho poznáme zlepšení?"}, {"type": "textarea", "label": "Sebereflexe studenta\nCo z doporučení přijímáte a co potřebujete ještě vyjasnit?"}, {"type": "input", "label": "Rozbor proběhl dne"}, {"type": "input", "label": "Posuzoval/a"}, {"type": "input", "label": "Další výstup nebo ověření změny"}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "Student připojí podklad ke konkrétní přípravě a rozboru ve svém portfoliu. Cvičný učitel hodnotí pozorovanou výuku; splnění praxe a zápočet posuzuje příslušný pedagog IVP.", "heading": false}]}, "arch-naslechu": {"id": "arch-naslechu", "title": "Záznam náslechové jednotky", "items": [{"type": "text", "text": "AKADEMICKÝ ROK 2026/2027", "heading": false}, {"type": "text", "text": "Záznam náslechové jednotky", "heading": true}, {"type": "text", "text": "Vyplňovací arch pro teoretickou i praktickou výuku", "heading": false}, {"type": "text", "text": "K čemu list slouží  Zachytí skutečný průběh výuky a poskytne podklad pro rozbor s vyučujícím a pedagogem IVP.", "heading": false}, {"type": "text", "text": "Kdy jej vyplnit  Základní údaje před hodinou, průběh během ní a rozbor bezprostředně po ní.", "heading": false}, {"type": "text", "text": "Jak postupovat  Jeden arch = jedna jednotka. Pro blok 02 i 03 připravte 10 teoretických a 2 praktické záznamy. Zaškrtnutí vždy doplňte příkladem.", "heading": false}, {"type": "input", "label": "Student IVP"}, {"type": "input", "label": "Škola a obor"}, {"type": "input", "label": "Datum náslechu a vyučující"}, {"type": "input", "label": "Třída nebo skupina a počet žáků"}, {"type": "input", "label": "Předmět a téma"}, {"type": "choice", "label": "Druh jednotky  Vyberte jednu možnost.", "multi": false, "options": ["Teoretická výuka", "Odborný výcvik", "Odborná praxe nebo cvičení"]}, {"type": "choice", "label": "Organizace práce  Označte vše, co platí.", "multi": true, "options": ["Frontální", "Individuální", "Individualizovaná", "Ve dvojicích nebo skupinách", "Projektová nebo týmová", "Jiná organizace"]}, {"type": "textarea", "label": "Výchovně vzdělávací cíl\nCo má žák na konci vědět, udělat nebo prokázat? Zachyťte také postoje či pracovní návyky, pokud byly sledovány."}, {"type": "text", "text": "Časový průběh výuky", "heading": true}, {"type": "text", "text": "Zapisujte hlavní změny činnosti, ne přepis každé věty. Ve sloupci „Co ověřit“ oddělte vlastní otázky a interpretace od pozorovaných dějů.", "heading": false}, {"type": "table", "label": "Zapisujte hlavní změny činnosti, ne přepis každé věty. Ve sloupci „Co ověřit“ oddělte vlastní otázky a interpretace od pozorovaných dějů.", "rows": [["Čas", "Co udělal učitel", "Co udělali žáci", "Co ověřit nebo rozebrat"], ["Příklad 10. min", "Předvedl postup a vyzval žáka k zopakování.", "Žák vynechal krok a po upozornění jej doplnil.", "Zvládne postup i bez nápovědy?"], ["", "", "", ""], ["", "", "", ""], ["", "", "", ""], ["", "", "", ""], ["", "", "", ""], ["", "", "", ""], ["", "", "", ""], ["", "", "", ""]]}, {"type": "text", "text": "Potřebujete-li více prostoru, tuto stránku zkopírujte. V záznamu žákům nepřiřazujte zbytečné osobní údaje; stačí například „žák A“ nebo „tři žáci“.", "heading": false}, {"type": "text", "text": "Rozbor pozorované výuky", "heading": true}, {"type": "text", "text": "Projděte všech sedm oblastí. Kde nemáte dostatek podkladů, označte „nepozorováno“ a připravte otázku pro vyučujícího.", "heading": false}, {"type": "choice", "label": "1  Cíl a jeho naplňování  Označte vše, co platí.", "multi": true, "options": ["Cíl byl žákům srozumitelný", "Cíl vyplynul až z činnosti", "Cíl nebyl zřejmý", "Nepozorováno"]}, {"type": "choice", "label": "2  Zpětná vazba a hodnocení  Označte vše, co platí.", "multi": true, "options": ["Učitel ověřil porozumění", "Žák dostal konkrétní doporučení", "Žák dostal prostor k opravě", "Nepozorováno"]}, {"type": "choice", "label": "3  Motivace a pozornost  Označte vše, co platí.", "multi": true, "options": ["Příklad z praxe", "Otázka nebo problém", "Ukázka", "Nepozorováno"]}, {"type": "choice", "label": "4  Aktivita a komunikace  Označte vše, co platí.", "multi": true, "options": ["Žáci převážně poslouchali", "Žáci sami řešili úkol", "Učitel přizpůsobil podporu", "Nepozorováno"]}, {"type": "textarea", "label": "Konkrétní příklad k oblastem 1 až 4\nUveďte číslo oblasti a situaci nebo odkaz na časový průběh."}, {"type": "text", "text": "Metody, pomůcky a další krok", "heading": true}, {"type": "choice", "label": "5  Metody výuky  Označte vše, co platí.", "multi": true, "options": ["Výklad nebo rozhovor", "Demonstrace či instruktáž", "Samostatná pracovní činnost", "Problémové řešení nebo projekt", "Opakování a procvičování", "Ověřování nebo zkoušení", "Jiné metody"]}, {"type": "textarea", "label": "Proč metoda odpovídala cíli\nDoložte, co díky ní žák skutečně dělal."}, {"type": "choice", "label": "6  Použité pomůcky a technika  Označte vše, co platí.", "multi": true, "options": ["Pracovní list nebo učebnice", "Nástroj, materiál nebo model", "Tabule nebo projekce", "Digitální program nebo video", "Jiné prostředky", "Nepozorováno"]}, {"type": "textarea", "label": "Jak prostředek pomohl učení\nUveďte použití, ne pouze název vybavení."}, {"type": "choice", "label": "7  Prostředí a další zjištění  Označte vše, co platí.", "multi": true, "options": ["Podmínky podporovaly soustředění", "Bylo nutné upravit organizaci", "Byla patrná podpora různých potřeb žáků", "Potřebuji ověřit další okolnosti"]}, {"type": "textarea", "label": "Doplnění z rozboru s vyučujícím\nCo se potvrdilo a co nyní vykládáte jinak?"}, {"type": "textarea", "label": "Co si odnáším do své výuky\nJeden postup a způsob, jak poznáte jeho účinek."}, {"type": "text", "text": "Co udělám dál", "heading": true}, {"type": "text", "text": "Doplňte elektronickou verzi podle pravidel svého bloku. Záznam uložte do portfolia a odevzdejte způsobem určeným IVP. Pro skupinový náslech je požadováno elektronické vyplnění a vložení do Moodle.", "heading": false}]}};